/// <summary>
/// service class for item state update batch job
/// </summary>
public class AVAItemStateUpdateService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// updates item state based on contract input
/// </summary>
/// <param name = "_contract">AVAItemStateUpdateContract</param>
public void updateItemState(AVAItemStateUpdateContract _contract)
{
    #OCCRetryCount

    try
    {
        AVAAVASCMItemStateUpdateV2::runItemState(_contract.parmItemStateTable(), false);
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
